Hier ist eine C++-Funktion, die auf einen std::string mit Markdown-formatiertem Text verweist und einen std::string mit HTML-formatiertem Text zurückgibt:

```cpp
#include <iostream>
#include <string>
#include <boost/algorithm/string.hpp>
#include <boost/algorithm/string/replace.hpp>
#include <boost/algorithm/string/join.hpp>
#include <boost/algorithm/string/split.hpp>

std::string markdownToHtml(const std::string& markdown) {
    // Remove leading and trailing whitespace
    boost::algorithm::trim(markdown);

    // Convert Markdown headings to HTML
    std::string newContent = boost::algorithm::replace_all_copy(markdown, "# ", "<h1>");
    newContent = boost::algorithm::replace_all_copy(newContent, "## ", "<h2>");
    newContent = boost::algorithm::replace_all_copy(newContent, "### ", "<h3>");
    newContent = boost::algorithm::replace_all_copy(newContent, "#### ", "<h4>");
    newContent = boost::algorithm::replace_all_copy(newContent, "##### ", "<h5>");
    newContent = boost::algorithm::replace_all_copy(newContent, "###### ", "<h6>");

    // Convert Markdown links to HTML
    std::vector<std::string> tokens;
    boost::algorithm::split(tokens, newContent, [](char c) { return c == ' '; });

    for (auto& token : tokens) {
        if (boost::starts_with(token, "[") && boost::ends_with(token, "]")) {
            std::string linkText = token.substr(1, token.size() - 2);
            std::string linkUrl;

            size_t openBracketPos = linkText.find_first_of("[");
            size_t closeBracketPos = linkText.find_last_of("]");
            if (openBracketPos != std::string::npos && closeBracketPos != std::string::npos) {
                std::string linkContent = linkText.substr(openBracketPos + 1, closeBracketPos - openBracketPos - 1);
                size_t urlPos = linkContent.find_first_of("(");
                if (urlPos != std::string::npos) {
                    linkUrl = linkContent.substr(urlPos + 1, std::string::npos);
                    linkUrl.erase(linkUrl.find_last_not_of(" \t") + 1);
                    linkUrl.erase(0, linkUrl.find_first_not_of(" \t"));
                    token = "<a href=\"" + linkUrl + "\">" + linkText.substr(0, openBracketPos) + linkContent.substr(0, urlPos) + "</a>";
                } else {
                    token = "<a href=\"" + linkContent + "\">" + linkText.substr(0, openBracketPos) + "</a>";
                }
            }
        }
    }
    newContent = boost::algorithm::join(tokens, " ");

    // Convert Markdown blockquotes to HTML
    newContent = boost::algorithm::replace_all_copy(newContent, "> ", "<blockquote>");

    // Convert Markdown code blocks to HTML
    newContent = boost::algorithm::replace_all_copy(newContent, "```\n", "<pre><code>");
    newContent = boost::algorithm::replace_all_copy(newContent, "```", "</code></pre>\n");

    return newContent;
}

int main() {
    std::string markdown = "Hello world!\n\n# Heading 1\n## Heading 2\n### Heading 3\n#### Heading 4\n##### Heading 5\n###### Heading 6\n\n[Link](https://example.com) [Link with title](https://example.com 'Title')\n\n> This is a blockquote.\n\n```
    This is a code block.
    ``";

    std::string html = markdownToHtml(markdown);

    std::cout << html << std::endl;

    return 0;
}
```

Die Funktion `markdownToHtml` nimmt einen `std::string` mit Markdown-Formatierung als Argument und gibt einen `std::string` mit der entsprechenden HTML-Formatierung zurück.

Die Funktion verwaltet einige der grundlegenden Markdown-Formate wie Überschriften, Links, Blockzitate und Code-Blöcke. Sie verwendet die Boost-Libraries `algorithm` und `string` für String-Manipulationen wie Splitting, Joining und Replace-All. Die Funktionslogik kann weiter verfeinert werden, um andere Markdown-Formate zu verarbeiten.

